void * /* <=== sng_malloc */ 
sng_malloc(size_t size)
{
    void *data;

    // Check memory allocation size
    if (size <= 0 || size > MALLOC_MAX_SIZE)
        return NULL;

    // Allocate memory
    if (!(data = malloc(size)))
        return NULL;

    // Initialize allocated memory
    memset(data, 0, size);
    return data;
}

void /* <=== packet_set_payload */ 
packet_set_payload(packet_t *packet, u_char *payload, uint32_t payload_len)
{
    // Free previous payload
    if (packet->payload)
        free(packet->payload);
    packet->payload_len = 0;

    // Set new payload
    if (payload) {
        packet->payload = malloc(payload_len + 1);
        memset(packet->payload, 0, payload_len + 1);
        memcpy(packet->payload, payload, payload_len);
        packet->payload[payload_len] = '\0';
        packet->payload_len = payload_len;
    }
}

